_WX_KE={木:"土",火:"金",土:"水",金:"木",水:"火"};function HL_wxState(_,n){return _===n?"旺":HL_WX_SHENG[n]===_?"相":HL_WX_SHENG[_]===n?"休":HL_WX_KE[_]===n?"囚":"死"}const HL_TRIGRAM_SENSE={乾:"天，主刚健、创始、决断",坤:"地，主柔顺、承载、包容",震:"雷，主发动、振作、奋起",巽:"风，主顺入、谦逊、循序",坎:"水，主险陷、智虑、坚韧",离:"火，主光明、附丽、明察",艮:"山，主静止、笃实、知止",兑:"泽，主和悦、沟通、交流"},HL64_SENSE={乾为天:"六爻纯阳，刚健自强，创始之象",坤为地:"六爻纯阴，厚德载物，柔顺包容",水雷屯:"草创之难，屯难之始，宜建侯图始",山水蒙:"蒙昧待启，启蒙之象，虚心则明",水天需:"云上于天，守需待时，时至乃行",天水讼:"争讼非善，以柔自守，贵在得中",地水师:"兵众之象，行师以律，任贤则吉",水地比:"亲辅之道，择善相依，宜早不宜迟",风天小畜:"以柔畜刚，蓄而未发，密云待雨",天泽履:"履危如平，循礼而行，慎则无虞",地天泰:"天地交泰，上下相通，小往大来",天地否:"天地不交，闭塞之世，守静待通",天火同人:"与人和同，公而不私，众志可成",火天大有:"日丽中天，富有盛大，惠及众人",地山谦:"谦德之至，裒多益寡，谦尊而光",雷地豫:"和乐豫备，顺以动则豫，逸中有备",泽雷随:"随顺时势，择善而从，随时之义",山风蛊:"积弊待治，整饬之象，治蛊须刚柔相济",地泽临:"临下以正，阳长之势，时至必进",风地观:"观仰化育，观我生进退，示下而化",火雷噬嗑:"噬而合之，明刑敕法，去梗乃通",山火贲:"文饰之象，质朴为本，饰而不失其实",山地剥:"阴盛剥阳，剥落之时，宜安静避害",地雷复:"一阳来复，不远而复，迷复则凶",天雷无妄:"不妄为则吉，动以天心，守正自安",山天大畜:"厚积之象，大畜其德，蓄极而发",山雷颐:"颐养之道，慎言节食，自求口实",泽风大过:"阳盛于中，担当非常，慎防过极",坎为水:"重险叠陷，履险以诚，维心亨通",离为火:"光明相继，丽乎正则亨，附丽之道",泽山咸:"交感相与，两情相悦，以虚受人",雷风恒:"恒久其道，立不易方，恒则可久",天山遁:"退避为宜，远害全身，退即是进",雷天大壮:"刚强壮盛，盛而以正，壮不可恃",火地晋:"日出地上，晋升向明，柔进上行",地火明夷:"明入地中，晦其明而守志，用晦乃明",风火家人:"正家之道，各正其位，内睦外顺",火泽睽:"背离相违，同中存异，小事可谐",水山蹇:"行有蹇滞，遇阻而反，反身修德",雷水解:"患难消解，既解宜静，赦过宥罪",山泽损:"损己益人，损中有得，损其可损",风雷益:"损上益下，迁善改过，其进无疆",泽天夬:"决而去之，刚断果决，扬善除恶",天风姤:"不期而遇，微邪初萌，防之在早",泽地萃:"聚而成群，会聚之时，敬慎防患",地风升:"木生地中，积小成高，柔以时升",泽水困:"泽中无水，困穷受制，守正待通",水风井:"井养不穷，守常济人，汲之则清",泽火革:"变革之时，顺天应人，革故鼎新",火风鼎:"鼎新之象，养贤凝命，去故取新",震为雷:"雷声发动，奋起振作，恐惧修省",艮为山:"两山相重，止于所当止，笃实安静",风山渐:"循序渐进，如鸿渐陆，徐行自达",雷泽归妹:"少女从长，守礼自持，妄进则凶",雷火丰:"日中之盛，盛大光明，宜守其中",火山旅:"行旅之象，柔顺处旅，居安防危",巽为风:"随风入物，谦顺行事，申命行事",兑为泽:"两泽相连，和悦相说，以诚相待",风水涣:"涣散离散，涣然冰释，聚散有时",水泽节:"节而有度，制数度议德行，苦节不可",风泽中孚:"诚信相孚，中心笃实，感物无私",雷山小过:"小事可过，行不宜大，敛翼低飞",水火既济:"已成之局，初吉终乱，守成防变",火水未济:"事未完成，慎终如始，穷而后通"},HL_YAO_WEI={1:"居一卦之始，如事之端基，宜潜养蓄势，未可骤进",2:"居下卦之中，得中道，进退有据，多平稳",3:"居下卦之终、内外交界，变动多端，宜慎宜勤",4:"近尊位而多惧，辅佐之位，进退须审时",5:"一卦尊位，得中主事，气数最旺之处",6:"居一卦之穷极，物极则变，盛时须知返"},HL_YAO_YIJI={1:{宜:"潜养蓄势、打牢根基，把手上的事做实",忌:"抢先出手、求速成、与人争锋"},2:{宜:"守中稳步、经营已有、以诚待人",忌:"冒进扩张、变更根本、争强出头"},3:{宜:"勤勉应变、两头照应、反复核验",忌:"疏忽细节、硬撑不退、使一处失守拖累全局"},4:{宜:"辅佐协调、贴近主事、审时进退",忌:"擅专越位、锋芒过露、骤然改向"},5:{宜:"主事担纲、定方向、聚拢资源",忌:"优柔失时、孤行独断、德不配位"},6:{宜:"收束总结、知止而退、把成果落到地",忌:"贪进不止、恋栈旧局、盛时再加码"}},HL_YAO_LI={1:"把时间与力气投在打基础上：补短板、学本事，把手上的小事做实",2:"把力气投在守成与经营上：稳住已有的局面与关系，不轻易改弦",3:"把力气投在应变与衔接上：两头都要顾到，勤于核验，勿使一处失守",4:"把力气投在辅佐与协调上：配合主事者，审时度势，进退有据",5:"把力气投在主事与担纲上：定方向、聚资源，担起该担的责任",6:"把力气投在收束与转化上：总结成果、知止而退，为下一局留余地"},HL_QI_YIJI={旺:{宜:"乘势而作、主动争取，把要事先办",忌:"恃强轻进、用力过猛、疏忽善后"},相:{宜:"借势推进、求人相助、顺势扩展",忌:"全然依赖外力、坐等其成、失其自主"},休:{宜:"养精蓄锐、整理内部、补短修漏",忌:"大举投入、向外扩张、耗散精神"},囚:{宜:"收敛守成、精简事务、量入为出",忌:"强行开拓、争讼对抗、重起炉灶"},死:{宜:"避锋守静、以退为进、保全根本",忌:"逆势强为、涉险冒进、与人争胜"}};window.HL_GAN_NUM=HL_GAN_NUM,window.HL_ZHI_NUM=HL_ZHI_NUM,window.HL_HELUO_GUA=HL_HELUO_GUA,window.HL_sanyuanOf=HL_sanyuanOf,window.HL_zhonggong=HL_zhonggong,window.HL_YT_TABLE=HL_YT_TABLE,window.HL_SHI_KEYS=HL_SHI_KEYS,window.HL_YT_REV_FEMALE_QIAN=HL_YT_REV_FEMALE_QIAN,window.HL_YT_REV_MALE_KUN=HL_YT_REV_MALE_KUN,window.HL_ZHIZUN=HL_ZHIZUN,window.HL_ying=HL_ying,window.HL_YUAN_QI=HL_YUAN_QI,window.HL_FAN_GUA=HL_FAN_GUA,window.HL_HUA_GONG=HL_HUA_GONG,window.HL_JI_YUE=HL_JI_YUE,window.HL_TRIGRAM_WX=HL_TRIGRAM_WX,window.HL_WX_SHENG=HL_WX_SHENG,window.HL_WX_KE=HL_WX_KE,window.HL_wxState=HL_wxState,window.HL_TRIGRAM_SENSE=HL_TRIGRAM_SENSE,window.HL64_SENSE=HL64_SENSE,window.HL_YAO_WEI=HL_YAO_WEI,window.HL_YAO_YIJI=HL_YAO_YIJI,window.HL_YAO_LI=HL_YAO_LI,window.HL_QI_YIJI=HL_QI_YIJI;
